"""Snowflake Data Metric Functions — the first platform-native check engine
(ADR 0036 §6, #895 slice 2).
"""

from __future__ import annotations

from typing import Any

from backend.app.datasources.base import CheckOutcome
from backend.app.datasources.monitors import (
    FRESHNESS,
    MonitorConfigError,
    _ident,
    monitor_expectation_type,
)
from backend.app.services.failure_classifier import safe_failure_reason

DMF_ENGINE = "dmf"

# expectation-kind metric types → the system DMF that computes them.
DMF_COLUMN_METRICS: dict[str, str] = {
    "dmf:null_count": "NULL_COUNT",
    "dmf:null_percent": "NULL_PERCENT",
    "dmf:duplicate_count": "DUPLICATE_COUNT",
    "dmf:unique_count": "UNIQUE_COUNT",
}
DMF_EXPECTATION_TYPES = tuple(DMF_COLUMN_METRICS)
# Higher-is-worse metrics band with thresholds; unique_count degrades DOWNWARD
# so thresholds are refused at author time (see module docstring).
DMF_UNBANDABLE_TYPES = frozenset({"dmf:unique_count"})
# The engine's supported-kind matrix (ADR 0036 §4). comparison / schema_drift / anomaly have run
# paths DMF cannot express (cross-dataset diff, introspection, baseline state).
DMF_KINDS = ("expectation", FRESHNESS)


def _quoted(name: object, *, what: str) -> str:
    """Validate (allowlist, #428 — via `_ident`, bounded echo) then quote (#476/#937)."""
    ident = _ident(name, what=what)
    return ident if ident == ident.lower() else f'"{ident}"'


def build_dmf_statement(
    *,
    kind: str,
    expectation_type: str,
    config: dict[str, Any],
    table: str,
    schema: str | None,
) -> str:
    """The ad-hoc invocation ``SELECT SNOWFLAKE.CORE.<FN>(SELECT … FROM <t>)``."""
    target = _quoted(table, what="table")
    if schema is not None:
        target = f"{_quoted(schema, what='schema')}.{target}"
    if kind == FRESHNESS:
        column = _quoted(config.get("column"), what="freshness column")
        return f"SELECT SNOWFLAKE.CORE.FRESHNESS(SELECT {column} FROM {target})"  # noqa: S608  # nosec B608
    function = DMF_COLUMN_METRICS.get(expectation_type)
    if kind != "expectation" or function is None:
        raise MonitorConfigError(
            f"the dmf engine cannot evaluate kind {kind!r} / type {expectation_type!r}"
        )
    column = _quoted(config.get("column"), what="column")
    return f"SELECT SNOWFLAKE.CORE.{function}(SELECT {column} FROM {target})"  # noqa: S608  # nosec B608


def _freshness_outcome(scalar: Any, config: dict[str, Any]) -> CheckOutcome:
    """Seconds-since-max → the monitor freshness outcome shape (age-hours metric)."""
    expectation_type = monitor_expectation_type(FRESHNESS)
    expected = {"monitor": FRESHNESS, "column": config.get("column"), "engine": DMF_ENGINE}
    if scalar is None:
        # An empty table has no max — same no-verdict rule as the monitor path.
        return CheckOutcome(
            expectation_type=expectation_type,
            success=False,
            errored=True,
            error_message="FRESHNESS returned no value (empty table?), freshness can't be assessed",
            expected_value=expected,
        )
    # Clamped at 0 like the monitor path (`_freshness_age_hours`): a max timestamp ahead of the
    # warehouse clock must trend 0.0 on BOTH engines, or the same data trends differently per
    # evaluator.
    age_hours = max(float(scalar) / 3600.0, 0.0)
    return CheckOutcome(
        expectation_type=expectation_type,
        success=True,  # binary fallback; thresholds band the age (authoring requires one)
        metric_value=age_hours,
        observed_value={"age_hours": round(age_hours, 3)},
        expected_value=expected,
    )


def _column_metric_outcome(
    scalar: Any, *, expectation_type: str, config: dict[str, Any]
) -> CheckOutcome:
    expected = {
        "engine": DMF_ENGINE,
        "metric": DMF_COLUMN_METRICS[expectation_type],
        "column": config.get("column"),
    }
    if scalar is None:
        return CheckOutcome(
            expectation_type=expectation_type,
            success=False,
            errored=True,
            error_message=f"{DMF_COLUMN_METRICS[expectation_type]} returned no value",
            expected_value=expected,
        )
    value = float(scalar)
    return CheckOutcome(
        expectation_type=expectation_type,
        success=True,  # thresholds band it (unique_count stays informational)
        metric_value=value,
        observed_value={"value": value},
        expected_value=expected,
    )


def evaluate_dmf_check(
    fetch_scalar: Any,
    *,
    kind: str,
    expectation_type: str,
    config: dict[str, Any],
    table: str,
    schema: str | None,
) -> CheckOutcome:
    """Evaluate ONE dmf-engine check; never raises — a failure is that check's
    classified ``error`` outcome (ADR 0036 §5), computed per check so a
    privilege problem on one metric never silences its siblings.
    """
    try:
        statement = build_dmf_statement(
            kind=kind,
            expectation_type=expectation_type,
            config=config,
            table=table,
            schema=schema,
        )
        scalar = fetch_scalar(statement)
        if kind == FRESHNESS:
            return _freshness_outcome(scalar, config)
        return _column_metric_outcome(scalar, expectation_type=expectation_type, config=config)
    except Exception as exc:
        # Classified, never raw (#900): a Snowflake DMF failure text can carry the statement (and
        # DMF privilege errors name objects).
        return CheckOutcome(
            expectation_type=expectation_type,
            success=False,
            errored=True,
            error_message=_classify_dmf_error(exc),
        )


def probe_dmf_capability(fetch_scalar: Any) -> dict[str, Any]:
    """Connection-test-time DMF availability probe (#1867) — a self-contained
    system-DMF call (no table access needed) that exercises exactly the
    edition + grant requirements a real dmf-engine check would hit. Never
    raises; the result is the `engine_capabilities["dmf"]` shape.
    """
    try:
        fetch_scalar("SELECT SNOWFLAKE.CORE.FRESHNESS(SELECT CURRENT_TIMESTAMP())")
        return {"available": True}
    except Exception as exc:
        return {"available": False, "reason": _classify_dmf_error(exc)}


def _classify_dmf_error(exc: Exception) -> str:
    """Fixed guidance for the DMF failure shapes live testing surfaced —
    Snowflake's own messages either mislead when generically classified (an
    unknown column read as "connection misconfigured") or name a limitation
    the author can only fix by knowing the platform rule.
    """
    text = str(exc)
    if "Invalid argument types" in text and "FRESHNESS" in text:
        return (
            "Snowflake's FRESHNESS data metric function accepts DATE, "
            "TIMESTAMP_LTZ and TIMESTAMP_TZ columns only — this column's type "
            "(commonly TIMESTAMP_NTZ) is not supported by the DMF. Use the "
            "GX-engine freshness monitor for this column instead."
        )
    if "invalid identifier" in text or "does not exist or not authorized" in text:
        # The second shape is Snowflake's missing-TABLE error (002003) — its "or not authorized"
        # tail must not fall through to the privilege branch below.
        return (
            "the configured column or table does not exist on the run target "
            "(or the role cannot see it) — check the check's column and the "
            "suite's run target"
        )
    if "Unknown function" in text or "not authorized" in text or "Insufficient privileges" in text:
        return (
            "the connection's role cannot invoke Snowflake system data metric "
            "functions — DMFs need Enterprise Edition and the "
            "SNOWFLAKE.DATA_METRIC_USER database role (or EXECUTE DATA METRIC "
            "FUNCTION) granted to the connection's role"
        )
    return safe_failure_reason(exc)
"""Connection-anchored check-engine capability map (ADR 0036)."""

from __future__ import annotations

from backend.app.db.models import GX_ENGINE

# Datasource connection types only — an orchestration provider offers no engines (it has no checks).
_OFFERED: dict[str, frozenset[str]] = {
    # 'dmf' rides SnowflakeCheckRunner.run_native_check (ADR 0036 §6, #895);
    # `test_offered_native_engines_are_runnable` pins offer ⇔ runner support.
    "snowflake": frozenset({GX_ENGINE, "dmf"}),
    "adls_gen2": frozenset({GX_ENGINE}),
    "s3": frozenset({GX_ENGINE}),
    "unity_catalog": frozenset({GX_ENGINE}),  # "dqx" trigger-gated (ADR 0036 §6)
    "iceberg": frozenset({GX_ENGINE}),
}


def engines_for(connection_type: str) -> frozenset[str]:
    """Engines ``connection_type`` offers; empty for a non-datasource type."""
    return _OFFERED.get(connection_type, frozenset())

  /** Require a fail or critical threshold (freshness has no in-config bound, so
   *  without one it can never fail — the #426 silent-green guard). */
  requireFailOrCritical?: boolean;
}

export interface ExpectationSpec {
  /** snake_case GX expectation type (or `monitor:<kind>`) sent to the backend. */
  type: string;
  /** Check kind (ADR 0012); defaults to `expectation` when omitted. */
  kind?: CheckKind;
  label: string;
  description: string;
  category: ExpectationCategory;
  /** The DQ dimension this check type measures (ADR 0038) — the editor's derived default. */
  dimension?: DqDimension;
  fields: ConfigField[];
  /** Present for monitor kinds — drives the threshold block's help/bounds/required. */
  thresholds?: MonitorThresholdSpec;
  /** Engine (ADR 0036); omitted = `gx`. Fixed `dmf` for the `dmf:*` types below. */
  engine?: CheckEngine;
  /** The backend rejects any threshold on this type; the editor hides the block. */
  noThresholds?: boolean;
  /**
   * GX has no SqlAlchemy metric provider for this type, so it errors on a SQL batch. Mirrors the
   * backend's `gx_runner.DATAFRAME_ONLY_EXPECTATION_TYPES`, which 422s it at author time — this
   * flag only keeps it out of the picker.
   */
  dataframeOnly?: boolean;
}

/** Freshness's type — same string for both engines, so it's a choice rather than a second entry. */
export const FRESHNESS_EXPECTATION_TYPE = 'monitor:freshness';

/** Mirrors `engines_for('snowflake')` (`backend/app/datasources/engines.py`). */
export function offersDmfEngine(connectionType: ConnectionType | undefined): boolean {
  return connectionType === 'snowflake';
}

/** True only for Freshness on a Snowflake connection — the one spec with an engine choice. */
export function showEngineChoiceFor(
  spec: ExpectationSpec | undefined,
  connectionType: ConnectionType | undefined,
): boolean {
  return spec?.type === FRESHNESS_EXPECTATION_TYPE && offersDmfEngine(connectionType);
}

/** The engine a check actually runs on. */
export function effectiveEngineFor(
  spec: ExpectationSpec | undefined,
  connectionType: ConnectionType | undefined,
  engineChoice: string | undefined,
): CheckEngine {
  if (spec?.engine) return spec.engine;
  if (showEngineChoiceFor(spec, connectionType)) return (engineChoice as CheckEngine) ?? 'gx';
  return 'gx';
}

const COLUMN: ConfigField = { name: 'column', label: 'Column', type: 'string' };

/** GX's row-wise tolerance kwarg — a fraction, not a percentage. */
export const MOSTLY_FIELD_NAME = 'mostly';

const MOSTLY_HELP =
  'Optional tolerance: the fraction of rows that must conform for the check to succeed — e.g. 0.95 = pass if ≥95% of rows conform. Leave blank to require every row. Severity thresholds still band the FULL unexpected-%, so a threshold below this tolerance can still warn/fail a run GX itself passed.';

/**
 * The `mostly` tolerance, offered on every row-wise expectation GX accepts it on. GX's own floor
 * is 0, which succeeds unconditionally forever — a check that can never fail is the #426
 * silent-green class, so the editor stops one step above it.
 */
const MOSTLY: ConfigField = {
  name: MOSTLY_FIELD_NAME,
  label: 'Tolerance',
  type: 'number',
  optional: true,
  min: 0.01,
  max: 1,
  step: 0.01,
  help: MOSTLY_HELP,
};

/** GX's own default is `any`; stated here so an untouched field submits what GX would do. */
const MATCH_ON: ConfigField = {
  name: 'match_on',
  label: 'Match on',
  type: 'select',
  optional: true,
  defaultValue: 'any',
  help: 'Whether a value must match ANY regex in the list (the default) or ALL of them.',
  options: [
    { value: 'any', label: 'Any regex in the list' },
    { value: 'all', label: 'Every regex in the list' },
  ],
};

/**
 * The type checks reach `mostly` only down GX's row-wise fallback; the whole-column dtype compare
 * it prefers is all-or-nothing, so the tolerance is inert there.
 */
const MOSTLY_TYPE_CHECK: ConfigField = {
  ...MOSTLY,
  help: `${MOSTLY_HELP} On a type check it applies only when GX falls back to its row-wise compare (see the Type hint above), not to the whole-column dtype compare.`,
};

/**
 * `type_` config-field name for `expect_column_values_to_be_of_type` — GX's own kwarg (trailing
 * underscore to dodge shadowing the Python builtin).
 */
export const TYPE_FIELD_NAME = 'type_';

const TYPE_FIELD_DEFAULT_HELP =
      help: 'Band the mismatch-% (non-matching rows over all logical rows; higher = worse, 0–100). Leave blank for a binary reconciled pass/fail.',
      max: 100,
    },
  },
  {
    type: COMPARISON_COLUMNS_EXPECTATION_TYPE,
    dimension: 'consistency',
    kind: 'comparison',
    label: 'Column-level reconciliation',
    description:
      'Same key-joined diff, counted per VALUE: each column reports its own matched / mismatched / additional-per-side counts. Pick this when you need to know WHICH columns drift, not just which rows.',
    category: 'Comparison',
    fields: [],
    thresholds: {
      help: 'Band the mismatch-% (non-matching value slots over all compared slots; higher = worse, 0–100). Leave blank for a binary reconciled pass/fail.',
      max: 100,
    },
  },
  // Snowflake DMF (ADR 0036 §6) — own expectation types, not a GX toggle.
  {
    type: 'dmf:null_count',
    engine: 'dmf',
    dimension: 'completeness',
    label: 'Null count (DMF)',
    description:
      'Snowflake’s system NULL_COUNT metric function, computed natively in the warehouse.',
    category: 'Snowflake DMF',
    fields: [COLUMN],
    thresholds: {
      help: 'Band the NULL count (higher = worse). A fail or critical threshold is required.',
      requireFailOrCritical: true,
    },
  },
  {
    type: 'dmf:null_percent',
    engine: 'dmf',
    dimension: 'completeness',
    label: 'Null percent (DMF)',
    description:
      'Snowflake’s system NULL_PERCENT metric function (0–100), computed natively in the warehouse.',
    category: 'Snowflake DMF',
    fields: [COLUMN],
    thresholds: {
      help: 'Band the NULL percent (0–100, higher = worse). A fail or critical threshold is required.',
      max: 100,
      requireFailOrCritical: true,
    },
  },
  {
    type: 'dmf:duplicate_count',
    engine: 'dmf',
    dimension: 'uniqueness',
    label: 'Duplicate count (DMF)',
    description:
      'Snowflake’s system DUPLICATE_COUNT metric function, computed natively in the warehouse.',
    category: 'Snowflake DMF',
    fields: [COLUMN],
    thresholds: {
      help: 'Band the duplicate count (higher = worse). A fail or critical threshold is required.',
      requireFailOrCritical: true,
    },
  },
  {
    type: 'dmf:unique_count',
    engine: 'dmf',
    noThresholds: true,
    dimension: 'uniqueness',
    label: 'Unique count (DMF)',
    description:
      'Snowflake’s system UNIQUE_COUNT metric function, computed natively in the warehouse. Degrades downward, so this type carries no thresholds — read the observed value directly.',
    category: 'Snowflake DMF',
    fields: [COLUMN],
  },
];

/** Lookup by expectation_type (for prefilling the editor in edit mode). */
export const EXPECTATION_BY_TYPE: Record<string, ExpectationSpec> = Object.fromEntries(
  EXPECTATION_CATALOG.map((e) => [e.type, e]),
);

/** Expectations grouped by category, in category order — drives the grouped
 *  expectation picker (antd Select optgroups / the dedicated check page). */
export const EXPECTATIONS_BY_CATEGORY: {
  category: ExpectationCategory;
  specs: ExpectationSpec[];
}[] = EXPECTATION_CATEGORIES.map((category) => ({
  category,
  specs: EXPECTATION_CATALOG.filter((e) => e.category === category),
}));

/**
 * Custom SQL (ADR 0019) is offered only on SQL-queryable connections — it runs a literal SQL
 * query.
 */
const CUSTOM_SQL_CATEGORY: ExpectationCategory = 'Custom SQL';

/**
 * Anomaly (#593) is gated the SAME as Custom SQL — `isSqlQueryable` and the backend's
 * `ANOMALY_CAPABLE_TYPES` are both exactly `{snowflake, unity_catalog}`.
 */
const ANOMALY_CATEGORY: ExpectationCategory = 'Anomaly';

/**
 * The freshness/volume monitor categories (ADR 0012) — offered on any monitor-capable datasource
 * (SQL datasources + Iceberg, `supportsMonitors`).
 */
const MONITOR_CATEGORY_SET = new Set<ExpectationCategory>(MONITOR_CATEGORIES);

const DMF_CATEGORY: ExpectationCategory = 'Snowflake DMF';

/** Grouped catalog filtered for a suite's datasource. */
export function expectationsByCategoryFor(
  connectionType: ConnectionType | undefined,
  alwaysIncludeType?: string,
): {
  category: ExpectationCategory;
  specs: ExpectationSpec[];
}[] {
  const sqlAllowed = connectionType !== undefined && isSqlQueryable(connectionType);
  const monitorAllowed = connectionType !== undefined && supportsMonitors(connectionType);
  const dmfAllowed = offersDmfEngine(connectionType);
  const selectedCategory = alwaysIncludeType
    ? EXPECTATION_BY_TYPE[alwaysIncludeType]?.category
    : undefined;
  const allowed = (category: ExpectationCategory): boolean => {
    if (category === selectedCategory) return true;
    if (category === CUSTOM_SQL_CATEGORY || category === ANOMALY_CATEGORY) return sqlAllowed;
    if (category === DMF_CATEGORY) return dmfAllowed;
    if (MONITOR_CATEGORY_SET.has(category)) return monitorAllowed;
    return true; // datasource-agnostic category
  };
  // A `dataframeOnly` spec errors on a SQL batch, so drop it per-SPEC rather than per-category —
  // it shares 'Column values' with a dozen types that run everywhere. The type being edited stays
  // visible, or the editor would silently switch the check to something else. Fails CLOSED on an
  // unknown connection type, like every gate above it: the connection load is best-effort, and
  // offering a type the backend then 422s wastes a whole filled-in form.
  const sqlBatch = connectionType === undefined || runsSqlBatch(connectionType);
  const specAllowed = (spec: ExpectationSpec): boolean =>
    spec.type === alwaysIncludeType || !spec.dataframeOnly || !sqlBatch;
  return EXPECTATIONS_BY_CATEGORY.filter((g) => allowed(g.category)).map((g) => ({
    category: g.category,
    specs: g.specs.filter(specAllowed),
  }));
}

/** A spec's config fields, adjusted for the suite's datasource (#520). */
export function configFieldsFor(
  spec: ExpectationSpec,
  connectionType: ConnectionType | undefined,
): ConfigField[] {
  if (

