def _persist_engine_capabilities(
    session: Session, conn: Connection, capabilities: dict[str, Any]
) -> None:
    """Soft signal, never a test failure: a connection can test successfully even
    when a native engine isn't available on it, so a persistence error here is
    logged and swallowed, not raised (#1867).
    """
    if not capabilities:
        return
    try:
        conn.engine_capabilities = capabilities
        session.commit()
    except Exception:
        # A commit failure here must not turn a genuinely successful connectivity
        # test into a 500.
        session.rollback()
        log.warning("connection_capability_probe_persist_failed", connection_id=str(conn.id))
        return
    log.info(
        "connection_capability_probe_completed",
        connection_id=str(conn.id),
        dmf_available=capabilities.get("dmf", {}).get("available"),
    )


def test_connection(
    session: Session,
    connection_id: uuid.UUID,
    *,
    secret_store: SecretStore,
) -> None:
    """Resolve the connection's secret and probe live connectivity."""
    conn = get_connection(session, connection_id)
    adapter = get_connection_adapter(conn.type)
    secret_optional = getattr(adapter, "secret_optional", False)

    secret: str | None = None
    if conn.secret_ref:
        try:
            secret = secret_store.get(conn.secret_ref)
        except SecretNotFoundError as exc:
            raise ConnectionTestFailedError(
                "credential could not be resolved", detail={"connection_id": str(connection_id)}
            ) from exc
    elif not secret_optional:
        raise ConnectionTestFailedError(
            "connection has no stored credential to test with",
            detail={"connection_id": str(connection_id)},
        )

    capabilities: dict[str, Any] = {}
    # Credential-health seam (#1697). An admin who has just re-authenticated must see the
    # signal clear on the same request, so a passing test stamps success here — this is the
    # one door that both `/test` and `/reauth` (which calls this function) go through.
    try:
        with credential_health.credential_use(session, conn):
            adapter.test(
                dict(conn.config),
                secret,
                **_capability_probe_kwargs(adapter, capabilities),
                **_extra_secrets(conn.config, secret_store),
            )
    except Exception as exc:
        log.warning(
            "connection_test_failed",
            connection_id=str(connection_id),
            error_type=type(exc).__name__,
        )
        # Don't echo the adapter exception to the client — it can carry DSN / credential fragments
        # (it's also kept out of the logs above).
        raise ConnectionTestFailedError(
            "connection test failed", detail={"connection_id": str(connection_id)}
        ) from exc

    log.info("connection_test_succeeded", connection_id=str(connection_id))
    _persist_engine_capabilities(session, conn, capabilities)


